/**
 * Grafana Faro RUM — the part that loads the SDK.
 *
 * Imported with import() by src/boot/faro.ts after the first render
 * (CORE-6333). Keep every @grafana/faro-* import (and through
 * @grafana/faro-web-tracing, all of OpenTelemetry) in this file; a static
 * import from a boot file puts them back on the render path and fails
 * scripts/check-boot-telemetry.cjs.
 *
 * Trace propagation: TracingInstrumentation below patches fetch/XHR when Faro
 * initialises and adds `traceparent` to API calls matching
 * propagateTraceHeaderCorsUrls. doc2-api must allow that header in CORS.
 * Calls made before this runs (the first ~1-3 s of a page load) carry none.
 */
import type { App } from 'vue';
import type { Router } from 'vue-router';
import {
  initializeFaro,
  ConsoleInstrumentation,
  ErrorsInstrumentation,
  FetchTransport,
  SessionInstrumentation,
  WebVitalsInstrumentation,
  LogLevel,
  type Faro,
} from '@grafana/faro-web-sdk';
import { TracingInstrumentation } from '@grafana/faro-web-tracing';
import { TransportItemType } from '@grafana/faro-core';
import { takePrebootErrors, getBootErrors } from 'src/utils/bootSafety';
import { flushFaroQueue, syncFaroUserFromSession } from 'src/boot/faro';

// Set once Faro is up; also the HMR re-initialisation guard.
let faroInstance: Faro | null = null;

/**
 * Preflight health check — probe the collector before initializing Faro.
 * If the collector is unreachable or returns non-2xx, returns false so we
 * skip initialization entirely (zero wasted requests).
 */
async function isCollectorHealthy(url: string): Promise<boolean> {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 3000);
    const resp = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: '{"logs":[],"exceptions":[],"measurements":[],"events":[],"traces":{"resourceSpans":[]},"meta":{}}',
      mode: 'cors',
      credentials: 'omit',
      signal: controller.signal,
    }).finally(() => clearTimeout(timeoutId));

    if (!resp.ok) {
      console.warn(
        `[Faro] Collector returned ${resp.status} — telemetry disabled.`,
        url,
      );
      return false;
    }
    return true;
  } catch {
    console.warn('[Faro] Collector unreachable — telemetry disabled.', url);
    return false;
  }
}

/**
 * Flush any errors captured before Faro was ready.
 *
 * Sources:
 *   - `window.__prebootErrors` / localStorage `docbits_preboot_errors` —
 *     populated by the inline <script> at the top of `index.html` which
 *     installs `window.onerror` / `unhandledrejection` listeners as early
 *     as possible so errors that happen during module load reach Faro.
 *   - `getBootErrors()` — errors captured by `safeBoot()` wrappers that
 *     ran before Faro was initialised. Without this, those earlier boot
 *     failures would be logged to console only and lost on page close.
 */
function flushPrebootEventsToFaro(faro: Faro): void {
  try {
    const preboot = takePrebootErrors();
    for (const evt of preboot) {
      const err = new Error(evt.message || 'preboot error');
      if (evt.stack) err.stack = evt.stack;
      faro.api.pushError(err, {
        type: evt.type,
        context: {
          source: evt.source || '',
          lineno: String(evt.lineno ?? ''),
          colno: String(evt.colno ?? ''),
          timestamp: String(evt.timestamp),
          phase: 'preboot',
        },
      });
    }

    const bootErrors = getBootErrors();
    for (const be of bootErrors) {
      const err = new Error(be.message || `boot error: ${be.bootName}`);
      if (be.stack) err.stack = be.stack;
      faro.api.pushError(err, {
        type: 'boot-error',
        context: {
          bootName: be.bootName,
          timestamp: be.timestamp,
          appVersion: be.appVersion,
          url: be.url,
          phase: 'boot',
        },
      });
    }
  } catch (err) {
    console.warn('[Faro] Failed to flush preboot/boot errors:', err);
  }
}

export interface FaroInitOptions {
  app: App;
  router?: Router;
  collectorUrl: string;
  appEnv: string | undefined;
  appVersion: string;
}

/**
 * Probe the collector, then initialise Faro and flush the errors recorded
 * before it was ready. Returns the instance, or null when skipped.
 */
export async function initFaro({
  app,
  router,
  collectorUrl,
  appEnv,
  appVersion,
}: FaroInitOptions): Promise<Faro | null> {
  // Prevent re-initialization during HMR
  if (faroInstance && import.meta.hot) {
    return faroInstance;
  }

  // Preflight: check collector health BEFORE initializing Faro.
  // If the collector is down, we skip entirely — zero wasted requests.
  const healthy = await isCollectorHealthy(collectorUrl);
  if (!healthy) {
    return null;
  }

  try {
    faroInstance = initializeFaro({
      app: {
        name: 'docbits-webapp',
        version: appVersion,
        environment: appEnv,
      },

      // Batching: send every 5s or when 50 items accumulate.
      // This produces ~0.2 req/s steady-state instead of per-item sends.
      batching: {
        enabled: true,
        sendTimeout: 5000,
        itemLimit: 50,
      },

      // Use the built-in FetchTransport — it handles batching, payload format,
      // and the isBatched() contract correctly (unlike our old custom transport).
      transports: [
        new FetchTransport({
          url: collectorUrl,
          // bufferSize: max queued requests when offline (default is fine)
          // concurrency: max parallel requests (default is fine)
        }),
      ],

      instrumentations: [
        // Errors: captures uncaught errors + unhandled promise rejections
        new ErrorsInstrumentation(),

        // Web Vitals: TTFB, FCP, LCP, CLS, FID, INP
        new WebVitalsInstrumentation(),

        // Console: capture warn + error only.
        // Override static disabledLevels to prevent feedback loop where Faro's own
        // console.debug messages get captured → queued → sent → more debug logs.
        (() => {
          ConsoleInstrumentation.defaultDisabledLevels = [
            LogLevel.TRACE,
            LogLevel.DEBUG,
          ];
          return new ConsoleInstrumentation();
        })(),

        // Sessions: track user journeys across page loads
        new SessionInstrumentation(),

        // Distributed tracing: propagate W3C traceparent to API calls.
        // ignoreUrls is handled automatically by FetchTransport.getIgnoreUrls()
        // which excludes the collector URL from tracing (prevents recursive traces).
        new TracingInstrumentation({
          instrumentationOptions: {
            propagateTraceHeaderCorsUrls: [
              /https:\/\/.*\.api\.docbits\.com/,
              /https:\/\/api\.docbits\.com/,
              /http:\/\/localhost:8080/,
            ],
          },
        }),
      ],

      sessionTracking: {
        enabled: true,
        persistent: true,
        samplingRate: 1.0,
      },

      // Suppress known noise from being captured as errors
      ignoreErrors: [
        /ResizeObserver/i,
        /chrome-extension:\/\//,
        /moz-extension:\/\//,
        // Dev-server module-load failures leak into Faro when the app is accessed via a
        // non-localhost address (WSL2, Docker, tunnel) so window.location.hostname is not
        // 'localhost', bypassing the early-return guard above. The error message still
        // contains the localhost:PORT URL that Vite uses internally to serve modules.
        /localhost:\d+/,
        /127\.0\.0\.1:\d+/,
      ],

      // Filter events before they reach the transport
      beforeSend: (event) => {
        // Skip debug-level logs that slipped through
        if (
          event.type === TransportItemType.LOG &&
          (event.payload as any)?.level === 'debug'
        ) {
          return null;
        }

        return event;
      },
    });

    // Expose faro globally for user context updates
    (window as any).__faro = faroInstance;
    app.config.globalProperties.$faro = faroInstance;

    // Route tracking — wrapped in try-catch to never affect navigation
    if (router) {
      router.afterEach((to, from) => {
        try {
          if (faroInstance) {
            faroInstance.api.pushEvent('route_change', {
              from: from.path,
              to: to.path,
              name: (to.name as string) || 'unknown',
            });
          }
        } catch {
          // Never let telemetry errors affect navigation
        }
      });
    }

    console.info(
      `[Faro] Initialized — ${appEnv} env, collector: ${collectorUrl}`,
    );

    // Flush any errors that happened before Faro was ready so they don't get lost.
    if (faroInstance) {
      flushPrebootEventsToFaro(faroInstance);
      flushFaroQueue(faroInstance);
    }

    // Attach org/user context for an already-established session (page reload,
    // returning tab). Fresh logins are covered by authSdkService.setSessionUser().
    // Without this, RUM data carries no org_id and cannot be org-scoped
    // server-side (DOCB-12254).
    syncFaroUserFromSession();
  } catch (error) {
    console.warn(
      '[Faro] Failed to initialize (app continues without telemetry):',
      error,
    );
  }

  return faroInstance;
}

// HMR cleanup
if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    faroInstance = null;
  });
}
